comp('C1','Identity and scoped intake','Code: validation',['T1'],['session: authenticated gateway token or absent','selection: connection reference or absent','complaint: untrusted text'],['scope: tenantId/customerId/connectionId/accountVersion or null','intake: caseId/status(VALID|NEED_INFO|UNAUTHORIZED|CANCELLED)'], 'Bind IDs from gateway and account registry, never from text. Refuse any mismatched/inactive selection before private reads. Case persisted transactionally with reason and owner; provisional cases contain no private billing data. GET account timeout 5s, one read retry, then NEED_INFO.', 'read')
comp('C2','Scoped evidence reader','Code: tools',['T2'],['scope: C1.scope required','caseId: durable intake ID'],['evidence: signed policy/version; billing recurring charge and cycle; outage intervals and source IDs; freshness','readStatus: OK|MISSING|CONFLICT|UNAVAILABLE'], 'Read only exact tenant/customer/active connection. Typed evidence includes observedAt, resourceVersion, allowed fields, source IDs. Timeout 5s per source, one read retry; missing, stale (>5 minutes for active state), conflicting or unavailable fields route to supervisor. Interval union clips to billing-cycle UTC boundaries; never double-count overlapping outages.', 'read')
